// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Sign in; sets the token cookie (a session cookie unless remember).
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Clear the token cookie.
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Me The signed-in user; extends the session (at most 7 days after login).
	// (GET /auth/me)
	Me(w http.ResponseWriter, r *http.Request)

	// (GET /block-kinds)
	ListBlockKinds(w http.ResponseWriter, r *http.Request)
	// ListCycles The user's cycles with their goal and training counts, the latest first.
	// (GET /cycles)
	ListCycles(w http.ResponseWriter, r *http.Request)

	// (POST /cycles)
	CreateCycle(w http.ResponseWriter, r *http.Request)
	// ImportCycle Save a whole cycle with its trainings at once, or nothing if any part is invalid (body up to 8 MiB).
	// (POST /cycles/import)
	ImportCycle(w http.ResponseWriter, r *http.Request)
	// DeleteCycle Soft-delete a cycle; its trainings leave it (keep) or are deleted too.
	// (DELETE /cycles/{id})
	DeleteCycle(w http.ResponseWriter, r *http.Request, id ID, params DeleteCycleParams)

	// (GET /cycles/{id})
	GetCycle(w http.ResponseWriter, r *http.Request, id ID)

	// (PUT /cycles/{id})
	UpdateCycle(w http.ResponseWriter, r *http.Request, id ID)
	// ListExerciseMaxes The 1RM history of all the user's exercises, newest first per exercise.
	// (GET /exercise-maxes)
	ListExerciseMaxes(w http.ResponseWriter, r *http.Request)

	// (DELETE /exercise-maxes/{id})
	DeleteExerciseMax(w http.ResponseWriter, r *http.Request, id ID)
	// ListExerciseRatings How the user rated their exercises.
	// (GET /exercise-ratings)
	ListExerciseRatings(w http.ResponseWriter, r *http.Request)
	// ListExercises The user's exercises with the names of their links.
	// (GET /exercises)
	ListExercises(w http.ResponseWriter, r *http.Request)

	// (POST /exercises)
	CreateExercise(w http.ResponseWriter, r *http.Request)
	// GetExercise One exercise with the ids of its links, for the exercise form.
	// (GET /exercises/{id})
	GetExercise(w http.ResponseWriter, r *http.Request, id ID)

	// (PUT /exercises/{id})
	UpdateExercise(w http.ResponseWriter, r *http.Request, id ID)
	// RateExercise Rate an exercise 1-5 with notes, replacing an earlier rating.
	// (POST /exercises/{id}/feedback)
	RateExercise(w http.ResponseWriter, r *http.Request, id ID)
	// AddExerciseMax Add a 1RM to an exercise's history; the newest is the current max.
	// (POST /exercises/{id}/maxes)
	AddExerciseMax(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /focuses)
	ListFocuses(w http.ResponseWriter, r *http.Request)

	// (POST /focuses)
	CreateFocus(w http.ResponseWriter, r *http.Request)

	// (GET /joints)
	ListJoints(w http.ResponseWriter, r *http.Request)

	// (GET /load-units)
	ListLoadUnits(w http.ResponseWriter, r *http.Request)

	// (POST /load-units)
	CreateLoadUnit(w http.ResponseWriter, r *http.Request)

	// (GET /muscle-groups)
	ListMuscleGroups(w http.ResponseWriter, r *http.Request)

	// (GET /rep-units)
	ListRepUnits(w http.ResponseWriter, r *http.Request)

	// (POST /rep-units)
	CreateRepUnit(w http.ResponseWriter, r *http.Request)
	// ListSessions The user's session templates with their size.
	// (GET /sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)

	// (POST /sessions)
	CreateSession(w http.ResponseWriter, r *http.Request)

	// (DELETE /sessions/{id})
	DeleteSession(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /sessions/{id})
	GetSession(w http.ResponseWriter, r *http.Request, id ID)
	// UpdateSession Replace a template; trainings keep their copies.
	// (PUT /sessions/{id})
	UpdateSession(w http.ResponseWriter, r *http.Request, id ID)
	// ExerciseStats The exercises done in workouts, most often first, with their rating.
	// (GET /stats/exercises)
	ExerciseStats(w http.ResponseWriter, r *http.Request)
	// ListTrainings The user's trainings with their size.
	// (GET /trainings)
	ListTrainings(w http.ResponseWriter, r *http.Request)

	// (POST /trainings)
	CreateTraining(w http.ResponseWriter, r *http.Request)

	// (DELETE /trainings/{id})
	DeleteTraining(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /trainings/{id})
	GetTraining(w http.ResponseWriter, r *http.Request, id ID)

	// (PUT /trainings/{id})
	UpdateTraining(w http.ResponseWriter, r *http.Request, id ID)
	// DuplicateTraining Copy a training (inactive) as the next phase, starting the Monday after it ends.
	// (POST /trainings/{id}/duplicate)
	DuplicateTraining(w http.ResponseWriter, r *http.Request, id ID)
	// GetWeek The tracker's week of the chosen active training (else the first).
	// (GET /week)
	GetWeek(w http.ResponseWriter, r *http.Request, params GetWeekParams)

	// (DELETE /whoop)
	DisconnectWhoop(w http.ResponseWriter, r *http.Request)
	// WhoopStatus Whether WHOOP can be connected (the server is configured) and whether it is.
	// (GET /whoop)
	WhoopStatus(w http.ResponseWriter, r *http.Request)
	// WhoopCallback Complete the connection; back to /track/settings (?whoop=error when it failed).
	// (GET /whoop/callback)
	WhoopCallback(w http.ResponseWriter, r *http.Request, params WhoopCallbackParams)
	// ConnectWhoop Send the browser to WHOOP to allow access; WHOOP returns it to the callback.
	// (GET /whoop/connect)
	ConnectWhoop(w http.ResponseWriter, r *http.Request)
	// ListWorkouts The workouts finished in [from, to) (at most a year), newest first.
	// (GET /workouts)
	ListWorkouts(w http.ResponseWriter, r *http.Request, params ListWorkoutsParams)
	// StartWorkout Start a workout of a slot of the week plan.
	// (POST /workouts)
	StartWorkout(w http.ResponseWriter, r *http.Request)
	// DeleteWorkout Discard a workout in progress or remove a finished one.
	// (DELETE /workouts/{id})
	DeleteWorkout(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /workouts/{id})
	GetWorkout(w http.ResponseWriter, r *http.Request, id ID)
	// FinishWorkout Finish a workout (a finished one only gets the notes), optionally dated to another day.
	// (POST /workouts/{id}/finish)
	FinishWorkout(w http.ResponseWriter, r *http.Request, id ID)
	// LogResult Log the score of a WOD block, or correct the one logged for it.
	// (PUT /workouts/{id}/results)
	LogResult(w http.ResponseWriter, r *http.Request, id ID)

	// (DELETE /workouts/{id}/results/{resultID})
	DeleteResult(w http.ResponseWriter, r *http.Request, id ID, resultID openapi_types.UUID)
	// LogSet Log a set, or correct the one logged at the same place.
	// (PUT /workouts/{id}/sets)
	LogSet(w http.ResponseWriter, r *http.Request, id ID)

	// (DELETE /workouts/{id}/sets/{setID})
	DeleteSet(w http.ResponseWriter, r *http.Request, id ID, setID openapi_types.UUID)

	// (DELETE /workouts/{id}/whoop)
	UnlinkWhoop(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /workouts/{id}/whoop)
	GetWorkoutWhoop(w http.ResponseWriter, r *http.Request, id ID)
	// LinkWhoop Link a WHOOP activity to a workout, fetching its data (again).
	// (PUT /workouts/{id}/whoop)
	LinkWhoop(w http.ResponseWriter, r *http.Request, id ID)
	// ListWhoopCandidates The WHOOP activities in [from, to) (the workout's local day), to pick one to link.
	// (GET /workouts/{id}/whoop/candidates)
	ListWhoopCandidates(w http.ResponseWriter, r *http.Request, id ID, params ListWhoopCandidatesParams)
}

